INSERT INTO shop.products (id,name,thumbnail,description,price,discount_price,popularity,quantity,category,created_at,updated_at) VALUES ('f3boue5hvtbv6ud','اپل واچ سری ۷ ','https://api.expertflutter.pro/storage/v1/object/public/shop-images/product_f3boue5hvtbv6ud_apple_watch_se_gold_aluminum_case_with_sport_band_1_572x572_1_SqCu135sJC.png','ساعت‌های هوشمند اپل از سری لوازم جانبی جذاب و پرکاربردی هستند که همواره طرفداران اپل برای رونمایی از آن‌ در کنار سایر دستگاه‌های اپل انتظار می‌کشند. اپل سری 7 ساعت‌های هوشمند خود را در دو سایز 41 میلی‌متر و 45 میلی‌متر به بازار روانه می‌کند. این ساعت هوشمند نسبت به ساعت‌های هوشمند سری قبل اپل با صفحه‌نمایش خمیده ارائه شده‌است. همچنین حاشیه‌ها نسبت به سری قبل کمتر خواهد بود. اپل ساعت هوشمند سری 7 خود را در رنگ‌های سبز، آبی، قرمز، مشکی و استارلایت (starlight) ارائه کرده‌است. جنس بدنه کماکان آلومینیوم است. در این ساعت ویژگی‌های منحصربه‌فردی همچون سنسور اندازه‌گیری اکسیژن خون و برنامه سلامت ECG وجود دارد. اپل واج سری 7 صفحه نمایش لمسی خازنی دارد. صفحه نمایش این ساعت هوشمند OLED بوده و در برابر ترک خوردگی و گرد و غبار مقاوم است. عملکرد باتری این ساعت هوشمند 18 ساعت خواهد بود. این باتری نسبت به نسل قبل ساعت هوشمند در حدود 33 درصد بهبود پیدا کرده است و تنها 45 دقیقه تا شارژ 80 درصد ساعت هوشمندتان فاصله زمانی وجود دارد. نور صفحه نمایش در سری جدید اپل‌واچ در حدود 70 درصد بهبود پیدا کرده‌است.
INSERT INTO shop.products (id,name,thumbnail,description,price,discount_price,popularity,quantity,category,created_at,updated_at) VALUES ('5vvww65pv6nviw6','آیفون ۱۳ پرومکس','https://api.expertflutter.pro/storage/v1/object/public/shop-images/product_5vvww65pv6nviw6_iphone_13_pro_max_silver_select_1_OIyq5lrgwn.png','گوشی‌های هوشمند خانواده آیفون 13 در قالب چهار گوشی هوشمند آیفون 13 پرو مکس، آیفون 13 پرو، آیفون 13‌ و آیفون 13 مینی معرفی شدند. پرچمداران جدید اپل این بار قدرتمند‌تر از همیشه پا به عرصه رقابت گذاشته اند تا در رقابتی بسیار جذاب، عملکردی بهتر به نسبت پرچمداران اندرویدی به نمایش بگذارد. از جمله اصلی‌ترین تغییرات در نظر گرفته شده برای این گوشی های هوشمند در مقایسه با پرچمداران خانواده آیفون 12 می‌توانیم به سنسور‌های دوربین قدرتمند‌تر، پردازنده فوق العاده با عملکرد بهتر و خیره کننده به نسبت نسل قبلی، تنوع رنگی بالا، صفحه نمایش به‌مراتب با‌کیفیت‌تراشاره کنیم. در این بررسی به‌سراغ آیفون 13 پرو مکس به عنوان گل سرسبد گوشی های هوشمند این خانواده رفته ایم تا ببینیم چه مشخصاتی را با خودش به همراه داشته و به نسبت آیفون 12 پرو مکس چه تغییرات در مشخصات فنی در نظر گرفته شده دارد.
INSERT INTO shop.products (id,name,thumbnail,description,price,discount_price,popularity,quantity,category,created_at,updated_at) VALUES ('jtkxewjcnfuh34c','ایر پاد پرو','https://api.expertflutter.pro/storage/v1/object/public/shop-images/product_jtkxewjcnfuh34c_0169029_airpods_pro_1_PEk5fJMklw.png','هدفون بلوتوثی اپل مدل AirPods Pro 2nd Generation در طول چند ماه به چنان محبوبیتی رسیده که به انتخاب اول کاربران تبدیل شده است.. گجت نسل جدید این کمپانی بزرگ یعنی هندزفری بی سیم اپل مدل airpods pro 2 با تراشه جدید H2 همراه شده است. این تراشه منجر به حذف نویز فعال و عملکرد دو برابر بهتره این مدل نسبت به قبل شده است. همچنین این ویژگی باعث شده تا صدا کیفیت بهتری پیدا کند. یکی دیگر از مشخصات عمده و اصلی ایرپاد پرو، کیفیت صوتی بی‌نظیری است که در مقابل محصولات مشابه سایر برندها دارد. شارژ کیس این محصول به کمک کابل لایتنینگ یا شارژ با استفاده از استاندارد Qi یا MagSafe جزو مشخصات مهم و اصلی ایرپاد پرو 2 اپل محسوب می‌شود. ایرپاد پرو2 اپل همچنین می‌تواند با شارژر اپل واچ نیز شارژ شود. با هر بار شارژ می‌توان تا 6 ساعت از از هدفون استفاده کرد. از این رو هندزفری بی سیم اپل مدل airpods pro 2 به عنوان یک ایرپاد استاندارد مطابق با نیاز کاربران طراحی شده است. کیس شارژ ایرپاد پرو در حال حاضر با شارژدهی تا 30 ساعت به عنوان مزیت دیگری برای خرید ایرپاد پرو محسوب می‌شود. از دیگر تغییرات مهمی که در هدفون بی‌سیم اپل مدل airpods pro 2nd generation به وجود آمده، می‌توان به این مورد اشاره کرد که عمر باتری در این سری بهبود یافته است. همچنین روی کیس ایرباد پرو 2 اسپیکری قرار گرفته که می‌توانید از آن برای پیدا کردن کیس استفاده کنید.
INSERT INTO shop.products (id,name,thumbnail,description,price,discount_price,popularity,quantity,category,created_at,updated_at) VALUES ('78n4wqor3hhnkju','مک بوک 13 اینچی','https://api.expertflutter.pro/storage/v1/object/public/shop-images/product_78n4wqor3hhnkju_macbook_png_image_1_8o4zlAGSfu.png','اپل در رویداد One More Thing خود از مک بوک پرو 2020 نیز رونمایی کرد. این مک بوک از صفحه نمایش 13 اینچی و پردازنده ویژه اپل به نام M1 و سیستم عاملmacOS Big Sur بهره می‌برد. این محصول همانند قبل با بدنه‌ی یکپارچه‌ی آلومینیومی، نمایشگر 13.3 اینچی رتینا با وضوح 1600× 2560 پیکسل و حاشیه‌‌های نسبتا باریک جزو چشم‌نوازترین اولترابوک‌های بازار به‌شمار می‌آید به گفته اپل این دستگاه نسبت به نسل قبل خود تا 3 برابر سریع ‌تر شده است. همچنین پردازنده گرافیکی هشت هسته‌ای M1 آن نیز 5 برابر سریع تر است. در نهایت سرعت این مک بوک 3 برابر بیشتر از نسل قبل است و لپ‌تاپ‌های ویندوزی پر فروش و هم‌رده با مک بوک پرو سرسع‌تر است. با وجود اینکه MacBook Air بدون فن طراحی شده است؛ اما اپل برای MacBook Pro فن تعبیه کرده است تا بتواند برای مدت طولانی تری عملیات های سنگین را انجام دهد.مک‌بوک پرو 13 اینچی از رم یکپارچه‌ی 8 یا 16 گیگابایتی بهره می‌برد و با حافظه‌ی SSD در ظرفیت‌های 256، 512، 1024 یا 2048 گیگابایتی به‌فروش می‌رسد. اولترابوک‌ حرفه‌ای اپل به‌ کمک باتری بزرگتر خود می‌تواند نسبت به مدل قبلی خود 10 ساعت شارژ بیشتری را نگه دارد. این باتری 58.2 وات‌ساعتی‌ تا 17 ساعت وب‌گردی یا 20 ساعت پخش فیلم کاربر را همراهی می‌کند و با شارژر 61 واتی USB-C دراختیار کاربر قرار می‌گیرد. برنامه‌نویسان به کمک آن می‌توانند با یک بار شارژ کردن دستگاه چهار ساعت بیشتر از گذشته برنامه‌نویسی کنند.دوربین مک‌بوک پرو 13 اینچی همانند گذشته از وضوح 720p بهره می‌برد؛ اما اکنون به‌لطف پردازنده‌ی سیگنال تصویر در داخل M1 می‌تواند تصاویری با نویز اندک و گستره‌ی دینامیکی وسیع‌تر ثبت کند. این اولترابوک 13 اینچی به‌ کمک Secure Enclave تراشه‌ی M1 امنیت را ازطریق Touch ID تأمین می‌کند و مانند همتای اینتلی‌اش دو پورت USB 4 با پشتیبانی از USB 3.1 Gen 2 (پهنای باند 10 گیگابیت‌برثانیه) پورت Thunderbolt 3 (پهنای باند 40 گیگابیت‌برثانیه) و اتصال یک نمایشگر 6K با نرخ 60 هرتز دراختیار کاربر می‌گذارد؛ اما هم‌اکنون از سازگاری با گرافیک اکسترنال خبری نیست.مک‌بوک پرو 13 اینچی کماکان از جک 3.5میلی‌متری هدفون بهره می‌برد و در بطن خود ماژول Wi-Fi 6 به‌همراه بلوتوث 5 دارد.
INSERT INTO shop.products (id,name,thumbnail,description,price,discount_price,popularity,quantity,category,created_at,updated_at) VALUES ('74vxtcnp4j587ll','آیفون SE 2022','https://api.expertflutter.pro/storage/v1/object/public/shop-images/product_74vxtcnp4j587ll_iphone_se_midnight_select_202203_1_7J1mQZzu23.png','سری SE گوشی‌های هوشمند شرکت اپل با بهره بردن از قیمت‌های ارزان‌تری به نسبت پرچمداران این شرکت، طرفداران بسیار زیادی در بین کاربران داشته‌اند و توانسته‌اند فروش بسیار خوبی را در بازار به خود اختصاص دهند. iPhone SE 2022 هم به عنوان یکی از گوشی‌های مقرون به‌صرفه این شرکت معرفی شد و مشخصات قدرتمندی را با خود به‌همراه داشت. این گوشی به صفحه‌نمایش با ابعاد 4.7 اینچ و رزولوشن 750×1334 مجهز شده که توانایی نمایش 326 پیکسل در هر اینچ را دارد. در قسمت پشتی تنها یک سنسور دوربین اصلی با رزولوشن 12 مگاپیکسل را شاهد هستیم که توانایی ضبط ویدیو با حداکثر کیفیت 4K سرعت 60 فریم در ثانیه را هم دارد. دوربین سلفی با رزولوشن 7 مگاپیکسل هم iPhone SE 2022 را همراهی می‌کند. این گوشی هوشمند به یکی از قدرتمند‌ترین پردازنده‌های اختصاصی اپل یعنی A15 بایونیک مجهز شده است. پردازنده‌ای که به‌راحتی از پس بازی‌های سنگین بر‌می‌آید و عملکرد بسیار خوبی را ارائه می‌کند. باتری 2018 میلی‌آمپر‌ساعت به‌ توانایی پشتیبانی از شارژر با توان 20 وات و مجهز به فناوری شارژ سریع از دیگر مشخصات در نظر گرفته شده برای iPhone SE 2022 هستند.
INSERT INTO shop.products (id,name,thumbnail,description,price,discount_price,popularity,quantity,category,created_at,updated_at) VALUES ('at0y1gm0t65j62j','شارژر بی سیم اپل','https://api.expertflutter.pro/storage/v1/object/public/shop-images/product_at0y1gm0t65j62j_194252192375_thumbnail_1_rSu5Ynp921.png','با استفاده از شارژر بی سیم می‌توان گوشی یا تبلت خود را به آسانی و سرعت بیشتری شارژ کرد. برند اپل جزو محبوب‌ترین برند‌های جهان است و استفاده از محصولات و گوشی‌های اپل امروزه بسیار متداول است. استفاده از اکسسوری‌های اپل با توجه به طراحی زیبا و کیفیت بالا مورد توجه بسیاری از کاربران و طرفداران این برند است. شارژر بی سیم اپل مدل MagSafe محصولی با کیفیت و طراحی زیبا از این برند است. با استفاده از این محصول می‌توان گوشی یا تبلت اپل را با سرعت بالاتری شارژ کرد. به همراه این شارژر بی‌سیم یک کابل USB-C جهت وصل شدن آن به سری شارژر ارائه می‌شود. MagSafe به گونه‌ای طراحی شده که با اتصال آن به سری شارژر گوشی خود دقیقا همان ولتاژ و آمپر خروجی سری شارژر را به گوشی شما می‌رساند. این محصول حدودا ۸۲ گرم وزن دارد که با گوشی‌های آیفون ۸ به بالا سازگار است.
